-- Widen only the channel checks; preserve all prior columns, values and response history.
CREATE TABLE csat_responses_messaging(resolution_id TEXT PRIMARY KEY REFERENCES conversation_resolutions(id),project_id TEXT NOT NULL,contact_id TEXT NOT NULL,channel TEXT NOT NULL CHECK(channel IN ('email','widget','sms','whatsapp','instagram','messenger')),scale TEXT NOT NULL CHECK(scale IN ('thumbs','five')),score INTEGER NOT NULL CHECK(score BETWEEN -1 AND 5 AND score!=0),reason TEXT NOT NULL,comment TEXT NOT NULL CHECK(length(comment)<=1000),revision INTEGER NOT NULL,updated_at INTEGER NOT NULL, response_surface TEXT NOT NULL DEFAULT 'unknown' CHECK(response_surface IN ('email','portal','widget','unknown','sms','whatsapp','instagram','messenger')), recovery TEXT NOT NULL DEFAULT 'unknown' CHECK(recovery IN ('unknown','recovered','not_recovered')));
INSERT INTO csat_responses_messaging(resolution_id,project_id,contact_id,channel,scale,score,reason,comment,revision,updated_at,response_surface,recovery) SELECT resolution_id,project_id,contact_id,channel,scale,score,reason,comment,revision,updated_at,response_surface,recovery FROM csat_responses;
DROP TABLE csat_responses;
ALTER TABLE csat_responses_messaging RENAME TO csat_responses;
CREATE TABLE csat_response_history_messaging(id TEXT PRIMARY KEY,resolution_id TEXT NOT NULL REFERENCES conversation_resolutions(id),project_id TEXT NOT NULL,contact_id TEXT NOT NULL,channel TEXT NOT NULL,scale TEXT NOT NULL,score INTEGER NOT NULL,reason TEXT NOT NULL,comment TEXT NOT NULL CHECK(length(comment)<=1000),revision INTEGER NOT NULL,created_at INTEGER NOT NULL, response_surface TEXT NOT NULL DEFAULT 'unknown' CHECK(response_surface IN ('email','portal','widget','unknown','sms','whatsapp','instagram','messenger')), recovery TEXT NOT NULL DEFAULT 'unknown' CHECK(recovery IN ('unknown','recovered','not_recovered')),UNIQUE(resolution_id,revision));
INSERT INTO csat_response_history_messaging(id,resolution_id,project_id,contact_id,channel,scale,score,reason,comment,revision,created_at,response_surface,recovery) SELECT id,resolution_id,project_id,contact_id,channel,scale,score,reason,comment,revision,created_at,response_surface,recovery FROM csat_response_history;
DROP TABLE csat_response_history;
ALTER TABLE csat_response_history_messaging RENAME TO csat_response_history;
CREATE INDEX csat_responses_project ON csat_responses(project_id,updated_at,resolution_id);
